 let mut report=fs::read_to_string(r("report-body.md")).unwrap();report.push_str("\n|Context|Accepted / OFF / ON ms|ON/OFF [bounds], wins|ON/accepted [bounds], wins|OFF/accepted calibration|\n|---|---:|---|---|---|\n");
 for name in["1x2-w16","1x2-w32","2x2-w16","2x2-w32"]{let c=&a["cells"][name];report.push_str(&format!("|{name}|{:.6} / {:.6} / {:.6}|{}|{}|{}|\n",c["accepted"]["median_ms"].as_f64().unwrap(),c["OFF"]["median_ms"].as_f64().unwrap(),c["ON"]["median_ms"].as_f64().unwrap(),stat(&a["pairs"][format!("{name}/ON/OFF")]),stat(&a["pairs"][format!("{name}/ON/accepted")]),stat(&a["pairs"][format!("{name}/OFF/accepted")])));}
